-- Researched map positions for AweenRayeh partner checkpoints that the OpenStreetMap
-- extract cannot place by name (63 of the 65 unplaced on 2026-11-03; الرام and كفر عقب have
-- no trustworthy position yet and stay unplaced). Keyed by the partner's city and name, kept
-- in the database so a position can be corrected without a release.
-- confidence: high / medium = matched to a mapped barrier; low = nearest barrier, may be a
-- different gate; unverified = given by a team member without a source. Apps label low and
-- unverified pins as approximate.

CREATE TABLE `checkpoint_positions` (
    `id` VARCHAR(191) NOT NULL,
    `city_ar` VARCHAR(100) NOT NULL,
    `name_ar` VARCHAR(191) NOT NULL,
    `latitude` DECIMAL(9, 6) NOT NULL,
    `longitude` DECIMAL(9, 6) NOT NULL,
    `confidence` ENUM('high', 'medium', 'low', 'unverified') NOT NULL,
    `source` VARCHAR(100) NOT NULL,
    `dataset_name` VARCHAR(191) NULL,
    `note` VARCHAR(500) NULL,
    `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updated_at` DATETIME(3) NOT NULL,

    UNIQUE INDEX `checkpoint_positions_city_ar_name_ar_key`(`city_ar`, `name_ar`),
    PRIMARY KEY (`id`),
    CONSTRAINT `checkpoint_positions_latitude_range` CHECK (`latitude` BETWEEN -90 AND 90),
    CONSTRAINT `checkpoint_positions_longitude_range` CHECK (`longitude` BETWEEN -180 AND 180)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

